<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Composition with Red, Blue and Yellow (1930) — Piet Mondrian</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,400;0,9..40,500;0,9..40,700;1,9..40,400&family=Space+Mono:wght@400;700&display=swap" rel="stylesheet" />
  <style>
    :root {
      --white: #f7f6f2;
      --pure-white: #ffffff;
      --grey: #e4e3de;
      --black: #111111;
      --red: #d40920;
      --blue: #1356a2;
      --yellow: #f7d842;
      --line: 8px;
    }

    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html {
      scroll-behavior: smooth;
      background-color: var(--white);
      color: var(--black);
      font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
      line-height: 1.5;
    }

    body {
      min-height: 100vh;
      border: var(--line) solid var(--black);
      background-color: var(--white);
    }

    .mono {
      font-family: 'Space Mono', monospace;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      font-size: 0.78rem;
    }

    /* Top Bar */
    .topbar {
      display: grid;
      grid-template-columns: 1fr auto auto;
      border-bottom: var(--line) solid var(--black);
      background: var(--pure-white);
    }

    .topbar-cell {
      padding: 1rem 1.5rem;
      display: flex;
      align-items: center;
    }

    .topbar-cell + .topbar-cell {
      border-left: var(--line) solid var(--black);
    }

    .topbar-brand {
      font-weight: 700;
      font-size: 1rem;
      letter-spacing: -0.01em;
    }

    .topbar-year {
      background: var(--yellow);
      font-weight: 700;
    }

    .topbar-source a {
      color: var(--black);
      text-decoration: none;
      font-weight: 700;
      border-bottom: 2px solid var(--black);
      transition: background-color 0.15s ease, color 0.15s ease;
    }

    .topbar-source a:hover {
      background: var(--black);
      color: var(--pure-white);
    }

    /* Hero Grid */
    .hero {
      display: grid;
      grid-template-columns: 1.05fr 0.95fr;
      border-bottom: var(--line) solid var(--black);
    }

    /* Left: Interactive Painting */
    .painting-stage {
      padding: 2.5rem;
      background: var(--grey);
      border-right: var(--line) solid var(--black);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 1.25rem;
    }

    .mondrian-canvas {
      width: 100%;
      max-width: 460px;
      aspect-ratio: 1 / 1;
      background: var(--black);
      border: var(--line) solid var(--black);
      display: grid;
      grid-template-columns: 24% 66% 10%;
      grid-template-rows: 34% 40% 13% 13%;
      gap: var(--line);
      box-shadow: 12px 12px 0 var(--black);
    }

    .cell {
      background: var(--pure-white);
      position: relative;
      cursor: pointer;
      transition: filter 0.15s ease, transform 0.15s ease;
    }

    .cell:hover {
      filter: brightness(0.96);
    }

    .cell.active {
      outline: 4px solid var(--black);
      outline-offset: -4px;
    }

    /* Painting geometry matching the fact sheet:
       - large red square at the top right
       - small blue square at the bottom left
       - small yellow rectangle at the bottom right
       - thick black lines on a white ground */
    .c-top-left-1 { grid-column: 1 / 2; grid-row: 1 / 2; }
